function resCard(r){
 const sv=S.saved[r.id],category=r.s==='legal'?'Legal help':'Work & learning';
 const sourceType=/^(USCIS|U\.S\.)|U\.S\. Department/.test(r.org)?'Government source':'Nonprofit resource';
 return `<article class="card resource-card" data-resource-card data-resource-category="${e(r.s)}"><span class="tag">${e(category)}</span><div class="meta"><span>${e(r.org)}</span><span class="tag gr">${e(sourceType)}</span></div><h3>${e(r.t)}</h3><p>${e(r.d)}</p><div class="row" style="gap:8px">${ext(r.u,'Open source','o')}<button class="btn o s" data-a="save" data-v="${e(r.id)}" aria-pressed="${!!sv}">${sv?'★ Saved':'☆ Save'}</button></div></article>`;
}
function applyImmigrationFilters(){
 const query=S.immQuery.trim().toLocaleLowerCase(),category=S.immCategory;
 let count=0,total=0;
 document.querySelectorAll('[data-resource-card]').forEach(card=>{
  total++;
  const matchesCategory=category==='all'||card.dataset.resourceCategory===category;
  const matchesQuery=!query||card.textContent.toLocaleLowerCase().includes(query);
  card.hidden=!(matchesCategory&&matchesQuery);
  if(!card.hidden)count++;
 });
 document.querySelectorAll('[data-resource-group]').forEach(group=>{
  group.hidden=!group.querySelector('[data-resource-card]:not([hidden])');
 });
 const status=document.querySelector('[data-resource-count]');
 if(status)status.textContent=`Showing ${count} of ${total} resources`;
 const empty=document.querySelector('[data-resource-empty]');
 if(empty)empty.hidden=count>0;
}
