const isDone=step=>{
 if(step.id==='county')return !!S.county.trim();
 if(step.id==='english')return Object.keys(S.ld).length>0;
 if(step.id==='interview')return Object.keys(S.ld).some(k=>k.startsWith('Job interviews'));
 if(step.id==='level')return !!S.done.level;
 return !!S.done[step.id];
};
