 <div class="nav-language"><h2>Language</h2>${Object.keys(T).map(k=>`<button data-a="footerLang" data-v="${k}" class="nav-language-option ${S.lang===k?'on':''}" lang="${k==='zh'?'zh-Hans':k}" ${S.lang===k?'aria-current="true"':''}>${T[k].n}</button>`).join('')}</div>
